# Package Deployment Script for DCS Olympus Plugin Manager\n# Creates a distribution package with all necessary files\n\nWrite-Host \"========================================\" -ForegroundColor Cyan\nWrite-Host \"Creating Deployment Package\" -ForegroundColor Cyan\nWrite-Host \"========================================\" -ForegroundColor Cyan\nWrite-Host \"\"\n\n# Check if executable exists\nif (-not (Test-Path \"dist\\DCSOlympusPluginManager.exe\")) {\n    Write-Host \"ERROR: Executable not found. Run build.ps1 first.\" -ForegroundColor Red\n    exit 1\n}\n\n# Create package directory\n$packageDir = \"DCSOlympusPluginManager_Package\"\nif (Test-Path $packageDir) {\n    Write-Host \"Removing existing package directory...\" -ForegroundColor Yellow\n    Remove-Item -Recurse -Force $packageDir\n}\n\nWrite-Host \"Creating package directory...\" -ForegroundColor Yellow\nNew-Item -ItemType Directory -Path $packageDir | Out-Null\n\n# Copy executable\nWrite-Host \"Copying executable...\" -ForegroundColor Yellow\nCopy-Item \"dist\\DCSOlympusPluginManager.exe\" -Destination $packageDir\n\n# Copy required files\nWrite-Host \"Copying required files...\" -ForegroundColor Yellow\n\nif (Test-Path \"olympus.json\") {\n    Copy-Item \"olympus.json\" -Destination $packageDir\n    Write-Host \"  - olympus.json\" -ForegroundColor Green\n} else {\n    Write-Host \"  ! olympus.json not found (required)\" -ForegroundColor Yellow\n}\n\nif (Test-Path \"atc.json\") {\n    Copy-Item \"atc.json\" -Destination $packageDir\n    Write-Host \"  - atc.json\" -ForegroundColor Green\n}\n\nif (Test-Path \"kokoro-v1.0.int8.onnx\") {\n    Copy-Item \"kokoro-v1.0.int8.onnx\" -Destination $packageDir\n    Write-Host \"  - kokoro-v1.0.int8.onnx\" -ForegroundColor Green\n}\n\n# Copy directories\nWrite-Host \"Copying directories...\" -ForegroundColor Yellow\n\nif (Test-Path \"databases\") {\n    Copy-Item \"databases\" -Destination $packageDir -Recurse\n    Write-Host \"  - databases/\" -ForegroundColor Green\n}\n\nif (Test-Path \"airspaces\") {\n    Copy-Item \"airspaces\" -Destination $packageDir -Recurse\n    Write-Host \"  - airspaces/\" -ForegroundColor Green\n}\n\n# Create scripts folder with example plugin\nWrite-Host \"Creating scripts folder...\" -ForegroundColor Yellow\nNew-Item -ItemType Directory -Path \"$packageDir\\scripts\" | Out-Null\n\nif (Test-Path \"scripts\\example_plugin\") {\n    Copy-Item \"scripts\\example_plugin\" -Destination \"$packageDir\\scripts\" -Recurse\n    Write-Host \"  - scripts/example_plugin/\" -ForegroundColor Green\n}\n\n# Copy documentation\nWrite-Host \"Copying documentation...\" -ForegroundColor Yellow\n\nif (Test-Path \"PLUGIN_README.md\") {\n    Copy-Item \"PLUGIN_README.md\" -Destination $packageDir\n    Write-Host \"  - PLUGIN_README.md\" -ForegroundColor Green\n}\n\nif (Test-Path \"BUILD_README.md\") {\n    Copy-Item \"BUILD_README.md\" -Destination $packageDir\n    Write-Host \"  - BUILD_README.md\" -ForegroundColor Green\n}\n\n# Create a README for the package\n$readmeContent = @\"\n# DCS Olympus Plugin Manager\n\n## Quick Start\n\n1. Double-click `DCSOlympusPluginManager.exe` to run\n2. The application will load all plugins from the `scripts/` folder\n3. Press Ctrl+C to stop\n\n## Configuration\n\nEdit `olympus.json` to configure:\n- Backend address and port\n- Authentication credentials\n- Other API settings\n\n## Creating Plugins\n\nSee `PLUGIN_README.md` for detailed plugin development guide.\n\nBasic plugin structure:\n```\nscripts/\n└── your_plugin/\n    ├── plugin.json\n    └── main.py\n```\n\n## Required Files\n\n- `DCSOlympusPluginManager.exe` - Main executable\n- `olympus.json` - Configuration file (REQUIRED)\n- `scripts/` - Plugins folder\n- `databases/` - Unit databases (optional)\n\n## Logs\n\nLogs are written to `olympus_plugins.log` in the same directory.\n\n## Support\n\nFor issues and documentation, see the included README files.\n\"@\n\nSet-Content -Path \"$packageDir\\README.txt\" -Value $readmeContent\nWrite-Host \"  - README.txt\" -ForegroundColor Green\n\n# Create ZIP archive\nWrite-Host \"\"\nWrite-Host \"Creating ZIP archive...\" -ForegroundColor Yellow\n$zipName = \"DCSOlympusPluginManager_Package.zip\"\n\nif (Test-Path $zipName) {\n    Remove-Item $zipName\n}\n\nCompress-Archive -Path $packageDir -DestinationPath $zipName\n\nWrite-Host \"\"\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"Package created successfully!\" -ForegroundColor Green\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"\"\nWrite-Host \"Package folder:\" -ForegroundColor Cyan\nWrite-Host \"  $(Resolve-Path $packageDir)\" -ForegroundColor White\nWrite-Host \"\"\nWrite-Host \"ZIP archive:\" -ForegroundColor Cyan\nWrite-Host \"  $(Resolve-Path $zipName)\" -ForegroundColor White\nWrite-Host \"\"\nWrite-Host \"The package is ready for distribution!\" -ForegroundColor Green\nWrite-Host \"\"\n